const listUserReviews = `-- name: ListUserReviews :many
SELECT pr.id, pr.order_item_id, pr.rating, pr.comment, pr.edit_count, pr.created_at, pr.updated_at,
       rr.id AS admin_reply_id, rr.content AS admin_reply, rr.updated_at AS admin_replied_at,
       o.id AS order_id, o.created_at AS order_created_at,
       oi.product_id, oi.brand_name, oi.product_name, oi.model, oi.image_url, oi.options::text AS options,
       oi.unit_price_vnd, oi.quantity, oi.line_total_vnd
FROM product_reviews pr
JOIN order_items oi ON oi.id = pr.order_item_id
JOIN orders o ON o.id = oi.order_id
LEFT JOIN review_replies rr ON rr.review_id = pr.id
WHERE o.user_id = $1
  AND ($2::smallint = 0 OR pr.rating = $2::smallint)
ORDER BY pr.created_at DESC, pr.id DESC
LIMIT $4 OFFSET $3
`

type ListUserReviewsParams struct {
	UserID       string
	RatingFilter int16
	OffsetCount  int32
	LimitCount   int32
}

type ListUserReviewsRow struct {
	ID             string
	OrderItemID    string
	Rating         int16
	Comment        string
	EditCount      int16
	CreatedAt      time.Time
	UpdatedAt      time.Time
	AdminReplyID   pgtype.UUID
	AdminReply     pgtype.Text
	AdminRepliedAt pgtype.Timestamptz
	OrderID        string
	OrderCreatedAt time.Time
	ProductID      string
	BrandName      string
	ProductName    string
	Model          string
	ImageUrl       string
	Options        string
	UnitPriceVnd   pgtype.Numeric
	Quantity       int64
	LineTotalVnd   pgtype.Numeric
}

func (q *Queries) ListUserReviews(ctx context.Context, arg ListUserReviewsParams) ([]ListUserReviewsRow, error) {
	rows, err := q.db.Query(ctx, listUserReviews,
		arg.UserID,
		arg.RatingFilter,
		arg.OffsetCount,
		arg.LimitCount,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListUserReviewsRow
	for rows.Next() {
		var i ListUserReviewsRow
		if err := rows.Scan(
			&i.ID,
			&i.OrderItemID,
			&i.Rating,
			&i.Comment,
			&i.EditCount,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.AdminReplyID,
			&i.AdminReply,
			&i.AdminRepliedAt,
			&i.OrderID,
			&i.OrderCreatedAt,
			&i.ProductID,
			&i.BrandName,
			&i.ProductName,
			&i.Model,
			&i.ImageUrl,
			&i.Options,
			&i.UnitPriceVnd,
			&i.Quantity,
			&i.LineTotalVnd,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

